begin;
create extension if not exists pg_cron;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon, authenticated, service_role;

create table public.profil (
 id uuid primary key references auth.users on delete cascade,
 ad text not null default '', tip text not null default 'bireysel' check(tip in ('bireysel','kurumsal')),
 telefon text, sehir text, eposta_ozet boolean not null default true, olusturma timestamptz not null default now()
);
create table private.yetkiler (kullanici_id uuid primary key references public.profil on delete cascade, admin boolean not null default false, engelli boolean not null default false);
create table public.kategoriler (id bigint generated by default as identity primary key, ust_id bigint references public.kategoriler, ad text not null, ad_en text not null, slug text not null unique, arac_tipi text, sira int not null default 0);
create table public.markalar (id bigint generated by default as identity primary key, ad text not null, tip text not null check(tip in ('otomobil','suv','motosiklet','ticari','minivan','is_makinesi','atv','karavan','deniz')), anahtar text not null, unique(anahtar,tip));
create table public.modeller (id bigint generated by default as identity primary key, marka_id bigint not null references public.markalar on delete cascade, ad text not null, anahtar text not null, bas_yil int, bit_yil int, unique(marka_id,anahtar), check(bas_yil is null or bas_yil >= 1950), check(bit_yil is null or bit_yil >= bas_yil));
create table public.oneriler (id uuid primary key default gen_random_uuid(), kullanici_id uuid not null default auth.uid() references public.profil, tip text not null, marka text not null, model text, durum text not null default 'beklemede' check(durum in ('beklemede','onaylandi','reddedildi')), olusturma timestamptz not null default now());
create table public.firmalar (id uuid primary key default gen_random_uuid(), kullanici_id uuid not null unique references public.profil on delete cascade, ad text not null, tur text not null check(tur in ('galeri','yetkili_satici','parca_tedarikcisi','ekspertiz_merkezi')), sehir text, logo text, kapak text, hakkinda text, telefon text, dogrulandi boolean not null default false, one_cikan boolean not null default false);
create table public.ilanlar (
 id uuid primary key default gen_random_uuid(), no bigint generated always as identity unique,
 kullanici_id uuid not null default auth.uid() references public.profil, kategori_id bigint not null references public.kategoriler,
 marka_id bigint references public.markalar, model_id bigint references public.modeller, diger_marka text, diger_model text,
 baslik text not null check(length(baslik) between 5 and 140), aciklama text not null default '' check(length(aciklama)<=12000),
 yil int check(yil between 1950 and 2200), km int check(km>=0), fiyat numeric(14,2) check(fiyat>=0), para_birimi text not null default 'GBP' check(para_birimi in ('GBP','EUR','USD','TL')),
 yakit text, vites text, sehir text check(sehir in ('Girne','Lefkoşa','Gazimağusa','İskele','Güzelyurt','Lefke')),
 detay jsonb not null default '{}', fotograflar text[] not null default '{}' check(cardinality(fotograflar)<=15), video text,
 durum text not null default 'taslak' check(durum in ('taslak','beklemede','yayinda','kaldirildi','satildi','suresi_doldu','arsiv','reddedildi')),
 onecikarma text check(onecikarma in ('seckin','hizli','prestij','vurgulu')), onecikarma_bitis timestamptz,
 uyari boolean not null default false, yayin timestamptz, bitis timestamptz, yukari timestamptz, satilma timestamptz,
 olusturma timestamptz not null default now(), guncelleme timestamptz not null default now()
);
create table private.ilan_haklari (ilan_id uuid primary key references public.ilanlar on delete cascade, ucretli boolean not null default false, abonelik_id uuid);
create unique index ilan_sasi on public.ilanlar (upper(regexp_replace(detay->>'sasi','\s','','g'))) where length(detay->>'sasi')>0 and durum not in ('arsiv','reddedildi');
create unique index ilan_plaka on public.ilanlar (upper(regexp_replace(detay->>'plaka_no','\s','','g'))) where length(detay->>'plaka_no')>0 and durum not in ('arsiv','reddedildi');
create table public.ilan_parca (ilan_id uuid not null references public.ilanlar on delete cascade, parca text not null check(parca in ('on_tampon','kaput','tavan','bagaj','arka_tampon','sol_on_camurluk','sag_on_camurluk','sol_on_kapi','sag_on_kapi','sol_arka_kapi','sag_arka_kapi','sol_arka_camurluk','sag_arka_camurluk')), durum text not null check(durum in ('orijinal','lokal_boyali','boyali','degisen','hasarli')), primary key(ilan_id,parca));
create table public.donanimlar (id bigint generated by default as identity primary key, grup text not null check(grup in ('Güvenlik','Sürüş Desteği','Konfor','İç Donanım','Dış Donanım','Multimedya')), ad text not null, ad_en text not null, arac_tipi text[] not null, unique(grup,ad));
create table public.ilan_donanim (ilan_id uuid not null references public.ilanlar on delete cascade, donanim_id bigint not null references public.donanimlar, primary key(ilan_id,donanim_id));
create table public.ilan_ekspertiz (ilan_id uuid primary key references public.ilanlar on delete cascade, dosya text not null, firma text not null, tarih date not null);
create table public.fiyat_gecmisi (id bigint generated always as identity primary key, ilan_id uuid not null references public.ilanlar on delete cascade, fiyat numeric(14,2), para_birimi text not null, tarih timestamptz not null default now());
create table public.paketler (
 id uuid primary key default gen_random_uuid(), ad text not null, hedef text not null check(hedef in ('bireysel','kurumsal')),
 ilan_kotasi int not null default 0 check(ilan_kotasi>=0), onecikarma_hakki int not null default 0 check(onecikarma_hakki>=0), sure_gun int not null check(sure_gun>0),
 fiyat numeric(14,2) check(fiyat>=0), para_birimi text not null default 'GBP' check(para_birimi in ('GBP','EUR','USD','TL')), aciklama text not null default '', aktif boolean not null default true, sira int not null default 0
);
create table public.paket_talepleri (
 id uuid primary key default gen_random_uuid(), kullanici_id uuid not null references public.profil, paket_id uuid not null references public.paketler,
 referans_kodu text not null unique default ('BC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),
 durum text not null default 'beklemede' check(durum in ('beklemede','odeme_bekliyor','dekont_yuklendi','onaylandi','reddedildi','iptal','suresi_doldu')),
 dekont_dosya text, kullanici_notu text not null default '', admin_notu text not null default '', makbuz_notu text not null default '',
 ozet jsonb not null, son_odeme timestamptz, olusturma timestamptz not null default now(), guncelleme timestamptz not null default now()
);
create unique index talep_tek on public.paket_talepleri(kullanici_id) where durum in ('beklemede','odeme_bekliyor','dekont_yuklendi');
create table public.abonelikler (
 id uuid primary key default gen_random_uuid(), kullanici_id uuid not null references public.profil, paket_id uuid not null references public.paketler, talep_id uuid not null unique references public.paket_talepleri,
 baslangic timestamptz not null default now(), bitis timestamptz not null, kalan_ilan int not null check(kalan_ilan>=0), kalan_onecikarma int not null check(kalan_onecikarma>=0), durum text not null default 'aktif' check(durum in ('aktif','bitti','iptal'))
);
alter table private.ilan_haklari add foreign key(abonelik_id) references public.abonelikler;
create table public.ayarlar (anahtar text primary key, deger jsonb not null);
create table public.bildirimler (id uuid primary key default gen_random_uuid(), kullanici_id uuid not null references public.profil on delete cascade, tur text not null, veri jsonb not null default '{}', tekil text unique, okundu boolean not null default false, olusturma timestamptz not null default now());
create table private.eposta_kuyrugu (id uuid primary key default gen_random_uuid(), bildirim_id uuid not null unique references public.bildirimler on delete cascade, kullanici_id uuid not null references public.profil on delete cascade, durum text not null default 'beklemede', deneme int not null default 0, olusturma timestamptz not null default now());
create table public.islem_kaydi (id bigint generated always as identity primary key, kullanici_id uuid, tablo text not null, kayit text, islem text not null, onceki jsonb, sonraki jsonb, tarih timestamptz not null default now());
create table public.favoriler (kullanici_id uuid not null default auth.uid() references public.profil on delete cascade, ilan_id uuid not null references public.ilanlar on delete cascade, fiyat_takibi boolean not null default false, primary key(kullanici_id,ilan_id));
create table public.bannerlar (id bigint generated always as identity primary key, yer int not null unique check(yer in (1,2)), baslik text not null, baslik_en text not null, metin text, metin_en text, resim text, baglanti text, aktif boolean not null default true);
create table public.yazilar (id uuid primary key default gen_random_uuid(), slug text not null unique, baslik text not null, baslik_en text not null, ozet text not null, ozet_en text not null, icerik text not null, icerik_en text not null, kapak text, kategori text not null, yayin timestamptz not null default now(), aktif boolean not null default true);

create index kategori_ust on public.kategoriler(ust_id);
create index ilan_sahip on public.ilanlar(kullanici_id,durum);
create index ilan_liste on public.ilanlar(durum,yayin desc);
create index ilan_model on public.ilanlar(marka_id,model_id,yil,para_birimi) where durum='yayinda';
create index ilan_kategori on public.ilanlar(kategori_id);
create index ilan_donanim_ara on public.ilan_donanim(donanim_id,ilan_id);
create index talep_sahip on public.paket_talepleri(kullanici_id,olusturma desc);
create index abonelik_sahip on public.abonelikler(kullanici_id,bitis) where durum='aktif';
create index bildirim_sahip on public.bildirimler(kullanici_id,olusturma desc);
create index fiyat_ilan on public.fiyat_gecmisi(ilan_id,tarih);
create index favori_ilan on public.favoriler(ilan_id);

create function private.admin() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from private.yetkiler where kullanici_id=auth.uid() and admin and not engelli)
$$;
create function private.uye() returns uuid language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null or not exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and not u.is_anonymous) or exists(select 1 from private.yetkiler where kullanici_id=auth.uid() and engelli) then raise exception 'Oturum veya doğrulanmış e-posta gerekli'; end if;
 return auth.uid();
end $$;
create function private.profil_ac() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.profil(id,ad,tip) values(new.id,left(coalesce(new.raw_user_meta_data->>'ad',''),100),case when new.raw_user_meta_data->>'tip'='kurumsal' then 'kurumsal' else 'bireysel' end);
 return new;
end $$;
create trigger profil_ac after insert on auth.users for each row execute function private.profil_ac();

create function private.kaydet() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.islem_kaydi(kullanici_id,tablo,kayit,islem,onceki,sonraki) values(auth.uid(),tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id',to_jsonb(new)->>'anahtar',to_jsonb(old)->>'anahtar'),tg_op,to_jsonb(old),to_jsonb(new));
 return coalesce(new,old);
end $$;
create function private.bildir(p_uid uuid,p_tur text,p_veri jsonb,p_tek text default null) returns void language plpgsql security definer set search_path='' as $$
declare b uuid;
begin
 insert into public.bildirimler(kullanici_id,tur,veri,tekil) values(p_uid,p_tur,p_veri,p_tek) on conflict(tekil) do nothing returning id into b;
 if b is not null and exists(select 1 from public.profil where id=p_uid and eposta_ozet) then insert into private.eposta_kuyrugu(bildirim_id,kullanici_id) values(b,p_uid); end if;
end $$;

create function private.talep_ac(p_paket uuid,p_not text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.uye(); p public.paketler; t uuid;
begin
 perform 1 from public.profil where id=u for update;
 select * into p from public.paketler where id=p_paket and aktif and hedef=(select tip from public.profil where id=u);
 if not found then raise exception 'Paket bu hesap için uygun değil'; end if;
 if exists(select 1 from public.paket_talepleri where kullanici_id=u and durum in ('beklemede','odeme_bekliyor','dekont_yuklendi')) then raise exception 'Bekleyen paket talebiniz var'; end if;
 if exists(select 1 from public.paket_talepleri where kullanici_id=u and olusturma>now()-interval '1 minute') then raise exception 'Bir dakika sonra tekrar deneyin'; end if;
 insert into public.paket_talepleri(kullanici_id,paket_id,kullanici_notu,ozet) values(u,p.id,left(coalesce(p_not,''),2000),to_jsonb(p)) returning id into t;
 return t;
end $$;
create function public.talep_ac(p_paket uuid,p_not text default '') returns uuid language sql set search_path='' as $$select private.talep_ac(p_paket,p_not)$$;

create function private.banka_bilgisi(p_talep uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=private.uye(); t public.paket_talepleri; a jsonb;
begin
 select * into t from public.paket_talepleri where id=p_talep and kullanici_id=u and durum='odeme_bekliyor' and son_odeme>now();
 if not found then raise exception 'Bu talep için banka bilgisi erişimi kapalı'; end if;
 select jsonb_object_agg(anahtar,deger) into a from public.ayarlar where anahtar in ('iban','hesap_sahibi','banka','odeme_notu');
 return a||jsonb_build_object('tutar',t.ozet->'fiyat','para_birimi',t.ozet->'para_birimi','referans_kodu',t.referans_kodu);
end $$;
create function public.banka_bilgisi(p_talep uuid) returns jsonb language sql set search_path='' as $$select private.banka_bilgisi(p_talep)$$;

create function private.dekont_ekle(p_talep uuid,p_dosya text) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=private.uye(); t public.paket_talepleri;
begin
 select * into t from public.paket_talepleri where id=p_talep and kullanici_id=u for update;
 if not found or t.durum not in ('odeme_bekliyor','reddedildi') or t.son_odeme is null or t.son_odeme<=now() then raise exception 'Dekont yükleme kapalı'; end if;
 if split_part(p_dosya,'/',1)<>u::text or split_part(p_dosya,'/',2)<>t.id::text or not exists(select 1 from storage.objects where bucket_id='dekontlar' and name=p_dosya) then raise exception 'Dekont bulunamadı'; end if;
 update public.paket_talepleri set dekont_dosya=p_dosya,durum='dekont_yuklendi',guncelleme=now() where id=t.id;
end $$;
create function public.dekont_ekle(p_talep uuid,p_dosya text) returns void language sql set search_path='' as $$select private.dekont_ekle(p_talep,p_dosya)$$;

create function private.talep_isle(p_talep uuid,p_durum text,p_not text,p_makbuz text,p_fiyat numeric) returns void language plpgsql security definer set search_path='' as $$
declare t public.paket_talepleri;
begin
 if not private.admin() then raise exception 'Yetki yok'; end if;
 select * into t from public.paket_talepleri where id=p_talep for update;
 if not found then raise exception 'Talep bulunamadı'; end if;
 if not ((p_durum='odeme_bekliyor' and t.durum in ('beklemede','reddedildi')) or (p_durum='onaylandi' and t.durum='dekont_yuklendi' and t.dekont_dosya is not null) or (p_durum='reddedildi' and t.durum in ('beklemede','odeme_bekliyor','dekont_yuklendi')) or (p_durum='iptal' and t.durum in ('beklemede','odeme_bekliyor','dekont_yuklendi','reddedildi'))) then raise exception 'Geçersiz durum geçişi'; end if;
 if p_durum='reddedildi' and length(trim(coalesce(p_not,'')))=0 then raise exception 'Red gerekçesi gerekli'; end if;
 if p_fiyat is not null then
  if p_fiyat<0 or p_durum<>'odeme_bekliyor' then raise exception 'Tutar yalnız ödeme bilgisi açılırken belirlenir'; end if;
  t.ozet:=jsonb_set(t.ozet,'{fiyat}',to_jsonb(p_fiyat));
 end if;
 if p_durum in ('odeme_bekliyor','onaylandi') and (t.ozet->>'fiyat') is null then raise exception 'Talep tutarı belirlenmeli'; end if;
 if p_durum='odeme_bekliyor' and exists(select 1 from public.ayarlar where anahtar in ('iban','hesap_sahibi','banka') and (deger#>>'{}')='') then raise exception 'Banka ayarlarını tamamlayın'; end if;
 update public.paket_talepleri set durum=p_durum,ozet=t.ozet,admin_notu=left(coalesce(p_not,''),2000),makbuz_notu=left(coalesce(p_makbuz,''),2000),son_odeme=case when p_durum='odeme_bekliyor' then now()+make_interval(days=>(select (deger#>>'{}')::int from public.ayarlar where anahtar='talep_zaman_asimi_gun')) else son_odeme end,guncelleme=now() where id=t.id;
end $$;
create function public.talep_isle(p_talep uuid,p_durum text,p_not text default '',p_makbuz text default '',p_fiyat numeric default null) returns void language sql set search_path='' as $$select private.talep_isle(p_talep,p_durum,p_not,p_makbuz,p_fiyat)$$;

create function private.abonelik_ac() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.durum='onaylandi' and old.durum<>'onaylandi' then
  insert into public.abonelikler(kullanici_id,paket_id,talep_id,bitis,kalan_ilan,kalan_onecikarma) values(new.kullanici_id,new.paket_id,new.id,now()+make_interval(days=>(new.ozet->>'sure_gun')::int),(new.ozet->>'ilan_kotasi')::int,(new.ozet->>'onecikarma_hakki')::int);
 end if;
 if new.durum<>old.durum then perform private.bildir(new.kullanici_id,'paket_talebi',jsonb_build_object('talep_id',new.id,'durum',new.durum,'referans',new.referans_kodu,'not',new.admin_notu)); end if;
 return new;
end $$;
create trigger abonelik_ac after update on public.paket_talepleri for each row execute function private.abonelik_ac();

create function private.kota(p_ilan uuid,p_islem text,p_tur text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=private.uye(); i public.ilanlar; a public.abonelikler; t text; n int; lim int; paid boolean;
begin
 select tip into t from public.profil where id=u for update;
 select * into i from public.ilanlar where id=p_ilan and kullanici_id=u for update;
 if not found then raise exception 'İlan bulunamadı'; end if;
 if p_islem='yayinla' then
  if i.durum not in ('taslak','kaldirildi','suresi_doldu','reddedildi') then raise exception 'İlan yayın işlemine uygun değil'; end if;
  if i.marka_id is not null and i.model_id is not null and not exists(select 1 from public.modeller where id=i.model_id and marka_id=i.marka_id and (bas_yil is null or i.yil>=bas_yil) and (bit_yil is null or i.yil<=bit_yil)) then raise exception 'Marka, model ve yıl uyuşmuyor'; end if;
  if (select (deger#>>'{}')::boolean from public.ayarlar where anahtar='sms_zorunlu') and not exists(select 1 from auth.users where id=u and phone_confirmed_at is not null) then raise exception 'Telefon doğrulaması gerekli'; end if;
  select ucretli into paid from private.ilan_haklari where ilan_id=i.id;
  select count(*) into n from public.ilanlar where kullanici_id=u and id<>i.id and durum in ('yayinda','beklemede') and bitis>now();
  select (deger#>>'{}')::int into lim from public.ayarlar where anahtar='ucretsiz_ilan_limiti';
  if not coalesce(paid,false) and i.durum='suresi_doldu' and exists(select 1 from private.ilan_haklari where ilan_id=i.id) and n>=lim then raise exception 'Yenilemek için aktif ilanlarından birini kaldır' using hint='hesabim.html'; end if;
  if not coalesce(paid,false) and (t='kurumsal' or n>=lim) then
   select * into a from public.abonelikler where kullanici_id=u and durum='aktif' and bitis>now() and kalan_ilan>0 order by bitis for update limit 1;
   if not found then raise exception 'Paket al veya mevcut ilanlarından birini kaldır' using hint='paketler.html'; end if;
   update public.abonelikler set kalan_ilan=kalan_ilan-1 where id=a.id;
   insert into private.ilan_haklari(ilan_id,ucretli,abonelik_id) values(i.id,true,a.id) on conflict(ilan_id) do update set ucretli=true,abonelik_id=a.id;
  else
   insert into private.ilan_haklari(ilan_id) values(i.id) on conflict do nothing;
  end if;
  update public.ilanlar set durum=case when uyari or (select (deger#>>'{}')::boolean from public.ayarlar where anahtar='ilan_onayi') then 'beklemede' else 'yayinda' end,yayin=now(),bitis=now()+interval '30 days',guncelleme=now() where id=i.id returning * into i;
 elsif p_islem='onecikar' then
  if i.durum<>'yayinda' or i.bitis<=now() or p_tur is null or p_tur not in ('seckin','hizli','prestij','vurgulu') then raise exception 'Öne çıkarma seçimi geçersiz'; end if;
  select * into a from public.abonelikler where kullanici_id=u and durum='aktif' and bitis>now() and kalan_onecikarma>0 order by bitis for update limit 1;
  if not found then raise exception 'Öne çıkarma hakkı yok' using hint='paketler.html'; end if;
  update public.abonelikler set kalan_onecikarma=kalan_onecikarma-1 where id=a.id;
  update public.ilanlar set onecikarma=p_tur,onecikarma_bitis=now()+make_interval(days=>(select (deger#>>'{}')::int from public.ayarlar where anahtar='onecikarma_gun')) where id=i.id returning * into i;
 elsif p_islem='yukari' then
  if i.durum<>'yayinda' or i.bitis<=now() or (i.yukari at time zone 'Asia/Nicosia')::date=(now() at time zone 'Asia/Nicosia')::date then raise exception 'Günde bir kez kullanılabilir'; end if;
  update public.ilanlar set yukari=now() where id=i.id returning * into i;
 elsif p_islem in ('kaldir','satildi','arsiv') then
  if p_islem='satildi' and i.durum<>'yayinda' then raise exception 'Yalnız yayındaki ilan satıldı olarak işaretlenebilir'; end if;
  update public.ilanlar set durum=case p_islem when 'kaldir' then 'kaldirildi' when 'satildi' then 'satildi' else 'arsiv' end,satilma=case when p_islem='satildi' then now() else satilma end,guncelleme=now() where id=i.id returning * into i;
 else raise exception 'Geçersiz işlem'; end if;
 return jsonb_build_object('id',i.id,'durum',i.durum,'bitis',i.bitis,'onecikarma',i.onecikarma,'onecikarma_bitis',i.onecikarma_bitis);
end $$;
create function public.kota(p_ilan uuid,p_islem text,p_tur text default null) returns jsonb language sql set search_path='' as $$select private.kota(p_ilan,p_islem,p_tur)$$;

create function private.ilan_kontrol() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.model_id is not null and not exists(select 1 from public.modeller where id=new.model_id and marka_id=new.marka_id) then raise exception 'Marka ile model uyuşmuyor'; end if;
 new.uyari:=(new.baslik||' '||new.aciklama) ~* '(kapora|ön[[:space:]]*ödeme|on[[:space:]]*odeme|iban|havale)';
 if tg_op='INSERT' then
  if auth.uid() is not null then
   perform private.uye();
   perform 1 from public.profil where id=auth.uid() for update;
   if (select count(*) from public.ilanlar where kullanici_id=auth.uid() and olusturma>now()-interval '1 hour')>=10 then raise exception 'İlan işlem sınırına ulaşıldı'; end if;
  end if;
 elsif new.baslik is distinct from old.baslik or new.aciklama is distinct from old.aciklama then
  if new.uyari and new.durum in ('yayinda','satildi') then new.durum:='beklemede'; end if;
 end if;
 new.guncelleme:=now();
 return new;
end $$;
create trigger ilan_kontrol before insert or update on public.ilanlar for each row execute function private.ilan_kontrol();
create function private.fiyat_kaydet() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='INSERT' or new.fiyat is distinct from old.fiyat or new.para_birimi is distinct from old.para_birimi then insert into public.fiyat_gecmisi(ilan_id,fiyat,para_birimi) values(new.id,new.fiyat,new.para_birimi); end if;
 return new;
end $$;
create trigger fiyat_kaydet after insert or update on public.ilanlar for each row execute function private.fiyat_kaydet();

create function private.admin_duzenle(p_tablo text,p_id text,p_veri jsonb) returns void language plpgsql security definer set search_path='' as $$
declare a public.abonelikler;
begin
 if not private.admin() then raise exception 'Yetki yok'; end if;
 if p_tablo='ayarlar' then
  if p_id not in ('iban','hesap_sahibi','banka','odeme_notu','ucretsiz_ilan_limiti','onecikarma_gun','talep_zaman_asimi_gun','ilan_onayi','sms_zorunlu','kurlar') then raise exception 'Ayar geçersiz'; end if;
  if p_id in ('ucretsiz_ilan_limiti','onecikarma_gun','talep_zaman_asimi_gun') and ((p_veri#>>'{}')::int<case when p_id='ucretsiz_ilan_limiti' then 0 else 1 end or (p_veri#>>'{}')::int>10000) then raise exception 'Ayar aralığı geçersiz'; end if;
  if p_id in ('sms_zorunlu','ilan_onayi') then perform (p_veri#>>'{}')::boolean; end if;
  update public.ayarlar set deger=p_veri where anahtar=p_id;
 elsif p_tablo='abonelikler' then
  select * into a from public.abonelikler where id=p_id::uuid for update;
  if not found then raise exception 'Abonelik bulunamadı'; end if;
  update public.abonelikler set kalan_ilan=coalesce((p_veri->>'kalan_ilan')::int,kalan_ilan),kalan_onecikarma=coalesce((p_veri->>'kalan_onecikarma')::int,kalan_onecikarma),bitis=coalesce((p_veri->>'bitis')::timestamptz,bitis),durum=coalesce(p_veri->>'durum',durum) where id=a.id;
 elsif p_tablo='ilanlar' then
  update public.ilanlar set durum=coalesce(p_veri->>'durum',durum),onecikarma=case when p_veri?'onecikarma' then p_veri->>'onecikarma' else onecikarma end,onecikarma_bitis=case when p_veri?'onecikarma_bitis' then (p_veri->>'onecikarma_bitis')::timestamptz else onecikarma_bitis end where id=p_id::uuid;
 else raise exception 'Tablo geçersiz'; end if;
end $$;
create function public.admin_duzenle(p_tablo text,p_id text,p_veri jsonb) returns void language sql set search_path='' as $$select private.admin_duzenle(p_tablo,p_id,p_veri)$$;
create function private.admin_talepler() returns setof public.paket_talepleri language plpgsql stable security definer set search_path='' as $$
begin
 if not private.admin() then raise exception 'Yetki yok'; end if;
 return query select * from public.paket_talepleri order by olusturma desc;
end $$;
create function public.admin_talepler() returns setof public.paket_talepleri language sql set search_path='' as $$select * from private.admin_talepler()$$;

create function private.bakim() returns void language plpgsql security definer set search_path='' as $$
declare a public.abonelikler; i public.ilanlar;
begin
 update public.paket_talepleri set durum='suresi_doldu',guncelleme=now() where (durum='beklemede' and olusturma<now()-make_interval(days=>(select (deger#>>'{}')::int from public.ayarlar where anahtar='talep_zaman_asimi_gun'))) or (durum in ('odeme_bekliyor','reddedildi') and son_odeme<=now());
 for a in select * from public.abonelikler where durum='aktif' and bitis<=now()+interval '7 days' loop
  perform private.bildir(a.kullanici_id,case when a.bitis<=now() then 'paket_bitti' else 'paket_bitiyor' end,jsonb_build_object('abonelik_id',a.id,'bitis',a.bitis),a.id::text||case when a.bitis<=now() then ':bitti:' else ':7gun:' end||a.bitis::text);
 end loop;
 update public.abonelikler set durum='bitti' where durum='aktif' and bitis<=now();
 for i in select * from public.ilanlar where durum='yayinda' and bitis between now() and now()+interval '3 days' loop
  perform private.bildir(i.kullanici_id,'ilan_bitiyor',jsonb_build_object('ilan_id',i.id,'bitis',i.bitis),i.id::text||':bitis:'||i.bitis::text);
 end loop;
 update public.ilanlar set durum='suresi_doldu' where durum='yayinda' and bitis<=now();
 update public.ilanlar set durum='arsiv' where durum='satildi' and satilma<=now()-interval '7 days';
 update public.ilanlar set onecikarma=null,onecikarma_bitis=null where onecikarma_bitis<=now();
end $$;
select cron.schedule('beta-car-bakim','*/15 * * * *','select private.bakim()');

create view public.piyasa_fiyatlari with(security_invoker=true) as
 with taban as (select distinct marka_id,model_id,yil,para_birimi from public.ilanlar where durum='yayinda' and bitis>now() and fiyat>0 and model_id is not null)
 select b.marka_id,b.model_id,b.yil,b.para_birimi,count(*) adet,percentile_cont(0.5) within group(order by i.fiyat) medyan,avg(i.fiyat) ortalama,min(i.fiyat) en_dusuk,max(i.fiyat) en_yuksek
 from taban b join public.ilanlar i on i.marka_id=b.marka_id and i.model_id=b.model_id and i.yil between b.yil-1 and b.yil+1 and i.para_birimi=b.para_birimi
 where i.durum='yayinda' and i.bitis>now() and i.fiyat>0 group by b.marka_id,b.model_id,b.yil,b.para_birimi having count(*)>=5;
create view public.ilan_kartlari with(security_invoker=true) as
 select i.*,m.ad marka,o.ad model,p.ad satici,f.ad firma,f.dogrulandi,
 (select count(*) from public.ilan_parca b where b.ilan_id=i.id) parca_sayisi,
 (select count(*) from public.ilan_parca b where b.ilan_id=i.id and b.durum in ('boyali','lokal_boyali')) boyali,
 (select count(*) from public.ilan_parca b where b.ilan_id=i.id and b.durum='degisen') degisen,
 (select count(*) from public.ilan_parca b where b.ilan_id=i.id and b.durum='hasarli') hasarli,
 exists(select 1 from public.ilan_ekspertiz e where e.ilan_id=i.id) ekspertizli,
 (select h.fiyat from public.fiyat_gecmisi h where h.ilan_id=i.id and h.para_birimi=i.para_birimi order by h.tarih desc,h.id desc offset 1 limit 1) onceki_fiyat
 from public.ilanlar i left join public.markalar m on m.id=i.marka_id left join public.modeller o on o.id=i.model_id left join public.profil p on p.id=i.kullanici_id left join public.firmalar f on f.kullanici_id=i.kullanici_id;
create view public.gelir_ozeti with(security_invoker=true) as
 select date_trunc('month',guncelleme) ay,ozet->>'para_birimi' para_birimi,count(*) talep_sayisi,sum((ozet->>'fiyat')::numeric) toplam from public.paket_talepleri where durum='onaylandi' and (select private.admin()) group by 1,2;
create function public.arac_sozlugu() returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('markalar',coalesce((select jsonb_agg(jsonb_build_array(id,ad,tip) order by ad) from public.markalar),'[]'),'modeller',coalesce((select jsonb_agg(jsonb_build_array(id,marka_id,ad,bas_yil,bit_yil) order by ad) from public.modeller),'[]'))
$$;
create function public.sayaclar() returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('kullanilmis',(select count(*) from public.ilanlar i join public.kategoriler k on k.id=i.kategori_id where i.durum='yayinda' and i.bitis>now() and (k.slug='kullanilmis' or k.slug like 'kullanilmis-%')),'sifir',(select count(*) from public.ilanlar i join public.kategoriler k on k.id=i.kategori_id where i.durum='yayinda' and i.bitis>now() and (k.slug='sifir' or k.slug like 'sifir-%')),'parca',(select count(*) from public.ilanlar i join public.kategoriler k on k.id=i.kategori_id where i.durum='yayinda' and i.bitis>now() and (k.slug='parca' or k.slug like 'parca-%')),'firma',(select count(*) from public.firmalar))
$$;

do $$ declare t text; begin
 foreach t in array array['profil','kategoriler','markalar','modeller','oneriler','firmalar','ilanlar','ilan_parca','donanimlar','ilan_donanim','ilan_ekspertiz','fiyat_gecmisi','paketler','paket_talepleri','abonelikler','ayarlar','bildirimler','islem_kaydi','favoriler','bannerlar','yazilar'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from anon,authenticated',t);
 end loop;
 foreach t in array array['yetkiler','ilan_haklari','eposta_kuyrugu'] loop execute format('alter table private.%I enable row level security',t); end loop;
 foreach t in array array['kategoriler','markalar','modeller','donanimlar','firmalar'] loop
  execute format('create policy oku on public.%I for select to anon,authenticated using(true)',t);
 end loop;
 foreach t in array array['kategoriler','markalar','modeller','donanimlar','paketler','bannerlar','yazilar'] loop
  execute format('create policy yonet on public.%I for all to authenticated using((select private.admin())) with check((select private.admin()))',t);
  execute format('grant select on public.%I to anon,authenticated',t);
  execute format('grant insert,update,delete on public.%I to authenticated',t);
 end loop;
 foreach t in array array['paket_talepleri','abonelikler','ayarlar','paketler','kategoriler','markalar','modeller','donanimlar','ilanlar','firmalar','bannerlar','yazilar'] loop execute format('create trigger islem_kaydi after insert or update or delete on public.%I for each row execute function private.kaydet()',t); end loop;
end $$;
create policy profil_oku on public.profil for select to anon,authenticated using(true);
create policy profil_yaz on public.profil for update to authenticated using(id=(select auth.uid())) with check(id=(select private.uye()));
grant select(id,ad,tip,sehir) on public.profil to anon,authenticated;
create function private.profilim() returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(p) from public.profil p where id=private.uye()$$;
create function public.profilim() returns jsonb language sql stable set search_path='' as $$select private.profilim()$$;
grant update(ad,telefon,sehir,eposta_ozet) on public.profil to authenticated;
grant select on public.firmalar to anon,authenticated;
create policy firma_yaz on public.firmalar for insert to authenticated with check(kullanici_id=(select private.uye()) and not dogrulandi and not one_cikan);
create policy firma_degistir on public.firmalar for update to authenticated using(kullanici_id=(select auth.uid())) with check(kullanici_id=(select private.uye()));
grant insert(kullanici_id,ad,tur,sehir,logo,kapak,hakkinda,telefon),update(ad,tur,sehir,logo,kapak,hakkinda,telefon) on public.firmalar to authenticated;
create policy paket_oku on public.paketler for select to anon,authenticated using(aktif);
create policy banner_oku on public.bannerlar for select to anon,authenticated using(aktif);
create policy yazi_oku on public.yazilar for select to anon,authenticated using(aktif and yayin<=now());
create policy ilan_oku on public.ilanlar for select to anon,authenticated using((durum='yayinda' and bitis>now()) or (durum='satildi' and satilma>now()-interval '7 days') or kullanici_id=(select auth.uid()) or (select private.admin()));
create policy ilan_ekle on public.ilanlar for insert to authenticated with check(kullanici_id=(select private.uye()) and durum='taslak');
create policy ilan_degistir on public.ilanlar for update to authenticated using(kullanici_id=(select auth.uid()) and durum<>'arsiv') with check(kullanici_id=(select private.uye()));
grant select on public.ilanlar,public.ilan_kartlari,public.piyasa_fiyatlari to anon,authenticated;
grant insert(kategori_id,marka_id,model_id,diger_marka,diger_model,baslik,aciklama,yil,km,fiyat,para_birimi,yakit,vites,sehir,detay,fotograflar,video),update(kategori_id,marka_id,model_id,diger_marka,diger_model,baslik,aciklama,yil,km,fiyat,para_birimi,yakit,vites,sehir,detay,fotograflar,video) on public.ilanlar to authenticated;
do $$ declare t text; begin
 foreach t in array array['ilan_parca','ilan_donanim','ilan_ekspertiz','fiyat_gecmisi'] loop
  execute format('grant select on public.%I to anon,authenticated',t);
  execute format('create policy oku on public.%I for select to anon,authenticated using(exists(select 1 from public.ilanlar i where i.id=ilan_id))',t);
  if t<>'fiyat_gecmisi' then
   execute format('grant insert,update,delete on public.%I to authenticated',t);
   execute format('create policy yaz on public.%I for all to authenticated using(exists(select 1 from public.ilanlar i where i.id=ilan_id and i.kullanici_id=(select private.uye()))) with check(exists(select 1 from public.ilanlar i where i.id=ilan_id and i.kullanici_id=(select private.uye())))',t);
  end if;
 end loop;
end $$;
create policy talep_oku on public.paket_talepleri for select to authenticated using(kullanici_id=(select auth.uid()) or (select private.admin()));
grant select(id,kullanici_id,paket_id,referans_kodu,durum,dekont_dosya,kullanici_notu,admin_notu,ozet,son_odeme,olusturma,guncelleme) on public.paket_talepleri to authenticated;
create policy abonelik_oku on public.abonelikler for select to authenticated using(kullanici_id=(select auth.uid()) or (select private.admin()));
grant select on public.abonelikler to authenticated;
create policy ayar_admin on public.ayarlar for select to authenticated using((select private.admin()));
grant select on public.ayarlar to authenticated;
create policy kayit_admin on public.islem_kaydi for select to authenticated using((select private.admin()));
grant select on public.islem_kaydi,public.gelir_ozeti to authenticated;
create policy bildirim_oku on public.bildirimler for select to authenticated using(kullanici_id=(select auth.uid()));
create policy bildirim_yaz on public.bildirimler for update to authenticated using(kullanici_id=(select auth.uid())) with check(kullanici_id=(select auth.uid()));
grant select,update(okundu) on public.bildirimler to authenticated;
create policy favori on public.favoriler for all to authenticated using(kullanici_id=(select auth.uid())) with check(kullanici_id=(select private.uye()));
grant select,insert,update,delete on public.favoriler to authenticated;
create policy oneri_oku on public.oneriler for select to authenticated using(kullanici_id=(select auth.uid()) or (select private.admin()));
create policy oneri_ekle on public.oneriler for insert to authenticated with check(kullanici_id=(select private.uye()) and durum='beklemede');
grant select,insert(tip,marka,model) on public.oneriler to authenticated;
grant usage,select on all sequences in schema public to authenticated;
grant all on all tables in schema public,private to service_role;
grant usage,select on all sequences in schema public to service_role;

